 v2x: f32, // @default 0 Note Field voice 2 x.
 v2y: f32, // @default 0 Note Field voice 2 y.
 v2z: f32, // @default 0 Note Field voice 2 z.
 v2energy: f32, // @default 0.2 Note Field voice 2 energy.
 v3x: f32, // @default 0 Note Field voice 3 x.
 v3y: f32, // @default 0 Note Field voice 3 y.
 v3z: f32, // @default 0 Note Field voice 3 z.
 v3energy: f32, // @default 0.2 Note Field voice 3 energy.
 v4x: f32, // @default 0 Note Field voice 4 x.
 v4y: f32, // @default 0 Note Field voice 4 y.
 v4z: f32, // @default 0 Note Field voice 4 z.
