  if (ctx.index == 0u) { at = vec3f(-2.65000, 2.65000 + ctx.params.v0y * 0.35, 2.30000); energy = ctx.params.v0energy; }
 if (ctx.index == 1u) { at = vec3f(0.10000, 2.65000 + ctx.params.v1y * 0.35, 2.30000); energy = ctx.params.v1energy; }
 if (ctx.index == 2u) { at = vec3f(2.65000, 2.55000 + ctx.params.v2y * 0.35, 2.30000); energy = ctx.params.v2energy; }
 if (ctx.index == 3u) { at = vec3f(-1.50000, 3.00000 + ctx.params.v3y * 0.35, 2.30000); energy = ctx.params.v3energy; }
