};
fn ring0(theta: f32, pitch: f32, t: f32) -> vec3f {
 let tilt = 0.720000 + 0.10 * sin(t * 0.23 + 0.0);
 let roll = -0.160000 + (pitch - 60.0) * 0.0060 + 0.060 * sin(t * 0.19 + 0.000000);
 let yaw = 0.080000;
 let v = vec3f(3.450000 * cos(theta), 1.350000 * sin(theta), 0.13 * sin(theta * 2.0 + t * 0.48));
