}

fn suspendedPose(v: vec3f, t: f32, degrees: f32) -> vec3f {
 let a=t*degrees*0.01745329252;let c=cos(a);let s=sin(a);
 return vec3f(v.x*c+v.z*s,v.y+0.045*sin(t*0.51),-v.x*s+v.z*c);
}
struct Params {
 pulse0: f32, // @default 0 Voice envelope.
 pitch0: f32, // @default 60 Voice pitch.
 pulse1: f32, // @default 0 Voice envelope.
