 o.emissive=reflection*fresnel*p.reflectionStrength*damp*roomFade+vec3f(0.003501,0.004102,0.005423)*(1.0-roomFade);
 return o;
}

struct SharedFrame { time: f32, deltaTime: f32, frameIndex: f32, randomSeed: f32, wallTime: f32, wallDelta: f32, absTime: f32, absFrame: f32, resolution: vec2f, pointer: vec4f, };
struct Params { amount: f32, };
@group(0) @binding(0) var inputSampler: sampler;
@group(0) @binding(1) var inputTexture: texture_2d<f32>;
@group(0) @binding(2) var<uniform> frameU: SharedFrame;
@group(0) @binding(3) var<uniform> params: Params;
@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let base = vec3f(0.009,0.009,0.01) + vec3f(0.025,0.026,0.028) * pow(max(0.0, sin(uv.y * 3.141592654)), 2.0);
 let cool = exp(-pow(abs((uv.x - 0.22) / 0.035), 8.0) - pow(abs((uv.y - 0.34) / 0.11), 8.0));
 let warm = exp(-pow(abs((uv.x - 0.73) / 0.045), 8.0) - pow(abs((uv.y - 0.48) / 0.21), 8.0));
 let strip = exp(-pow(abs((uv.y - 0.22) / 0.018), 2.0)) * (0.3 + 0.7 * pow(sin(uv.x * 3.141592654), 2.0));
