@fragment fn fs(@location(0) uv: vec2f) -> @location(0) vec4f {
 let original = textureSampleLevel(inputTexture,inputSampler,uv,0.0);
 let depth = viewDistance(uv);
 let radius = min(2.5,abs(depth-params.focusDistance) / max(depth,1.0) * params.aperture);
 var sum = original.rgb * 2.0;
 var total = 2.0;
 var bloom = vec3f(0.0);
 for (var i=0u;i<12u;i++) {
  let a = f32(i) * 2.39996323;
  let disk = vec2f(cos(a),sin(a)) * sqrt((f32(i)+0.5)/12.0);
  let tap = clamp(uv + disk * radius / frameU.resolution,vec2f(0.0),vec2f(1.0));
  let otherDepth = viewDistance(tap);
  let weight = mix(0.08,1.0,1.0-smoothstep(0.5,2.0,abs(depth-otherDepth)));
  sum += textureSampleLevel(inputTexture,inputSampler,tap,0.0).rgb * weight;
  total += weight;
  let glint = textureSampleLevel(inputTexture,inputSampler,clamp(uv+disk*4.0/frameU.resolution,vec2f(0.0),vec2f(1.0)),0.0).rgb;
  bloom += max(glint-vec3f(0.85),vec3f(0.0));
 }
 let c = sum/total + bloom * (0.028/12.0);
 let p = uv * 2.0-1.0;
 let vignette = 1.0-0.20*smoothstep(0.28,1.7,dot(p,p));
 let airUv = (uv-vec2f(0.20,0.20))*vec2f(1.25,1.8);
