};
fn surface(s: SurfaceIn,p: Params) -> SurfaceOut {
 var o=surfaceDefaults(s);
 let rawNormal=normalize(s.normal);let v=normalize(s.eye-s.world);
 let brushPhase=s.uv.y*350.0+0.3*sin(s.uv.x*70.0);
 let brush=sin(brushPhase)*(1.0-smoothstep(0.8,2.0,fwidth(brushPhase)));
 let tangent=cross(rawNormal,vec3f(0.13,1.0,0.21));
 let n=normalize(rawNormal+tangent*brush*0.008);
 let incidence=abs(dot(n,v));let r=reflect(-v,n);
 let thickness=420.0+115.0*sin(s.uv.x*5.0+p.phase)+35.0*sin(s.uv.x*13.0);
 let optical=12.566370614*1.45*thickness*sqrt(0.48+0.52*incidence*incidence)/vec3f(650.0,530.0,450.0);
 let raw=0.5+0.5*cos(optical+vec3f(0.0,0.2,0.4));let low=min(raw.r,min(raw.g,raw.b));
 let chroma=max(raw-vec3f(low*0.90),vec3f(0.0));let spectrum=chroma/max(max(chroma.r,chroma.g),max(chroma.b,0.05));
 let key=pow(max(0.0,dot(r,normalize(vec3f(-0.65,0.5,0.58)))),32.0);
 let rim=pow(max(0.0,dot(r,normalize(vec3f(0.8,0.22,-0.5)))),24.0);
 let panel=pow(max(0.0,dot(r,normalize(vec3f(0.1,0.85,0.35)))),9.0);
 let narrow=pow(max(0.0,dot(r,normalize(vec3f(-0.25,0.72,-0.64)))),90.0);
 let reflection=key*2.3*(1.0+0.10*p.pulse*p.life)+rim*1.8+panel*0.40+pow(1.0-incidence,4.0)*0.15;
 let coating=mix(vec3f(0.36,0.44,0.52),spectrum,clamp(p.richness+0.15,0.0,1.0));
 o.albedo=vec4f(0.0,0.0,0.0,1.0);
 o.emissive=coating*reflection*(0.06+0.94*pow(1.0-incidence,2.0))+vec3f(1.0,0.88,0.67)*narrow*0.50;
 return o;
}

